        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function FormField(options) {
      var helpMarkup = options.helpText
        ? '<p class="field-help" id="' + options.id + '-help">' + escapeHtml(options.helpText) + "</p>"
        : "";

      return (
        '<div class="form-field">' +
          '<label for="' + options.id + '">' + escapeHtml(options.label) + "</label>" +
          '<input' +
            ' id="' + options.id + '"' +
            ' name="' + options.name + '"' +
            ' type="' + options.type + '"' +
            ' placeholder="' + escapeHtml(options.placeholder || "") + '"' +
            (options.required ? " required" : "") +
            (options.autocomplete ? ' autocomplete="' + options.autocomplete + '"' : "") +
            (options.inputMode ? ' inputmode="' + options.inputMode + '"' : "") +
            ' aria-describedby="' + (options.helpText ? options.id + '-help ' : "") + options.id + '-error"' +
          ">" +
          helpMarkup +
          '<p class="field-error" id="' + options.id + '-error" hidden></p>' +
        "</div>"
      );
    }

    function ContactForm() {
      return (
        '<section class="contact-panel">' +
          '<form id="support-form" novalidate>' +
            FormField({
              id: "fullName",
              name: "fullName",
              label: "Full name",
              type: "text",
              placeholder: "Jordan Lee",
              required: true,
              autocomplete: "name"
            }) +
            FormField({
              id: "email",
              name: "email",
              label: "Email address",
              type: "email",
              placeholder: "jordan@example.com",
              required: true,
              autocomplete: "email"
            }) +
            FormField({
              id: "phone",
              name: "phone",
              label: "Phone number",
              type: "tel",
              placeholder: "+1 555-123-4567",
              autocomplete: "tel",
              inputMode: "tel",
