          '<section class="support-card">' +
            '<div class="support-copy">' +
              '<p class="eyebrow">Support</p>' +
              "<h1>Tell us how we can help.</h1>" +
              "<p>Send your details and a member of our support team will follow up shortly. Required fields stay quiet until you interact or submit.</p>" +
